let saleStatusPromise = null;
export const loadSaleStatus = () => {
  if (!saleStatusPromise) {
    saleStatusPromise = Promise.all(
      SALE_STATUS_URLS.map((url) =>
        fetch(url)
          .then((r) => (r.ok ? r.json() : {}))
          .catch(() => ({}))
      )
    ).then((parts) => Object.assign({}, ...parts));
  }
  return saleStatusPromise;
};

